NAV=[('/about','퍼스트 소개'),('/spaces','공간'),('/guide','이용 안내'),('/pickup','픽업 서비스'),('/blog','블로그')]

def esc(t): return html.escape(str(t),quote=True)
def button(url,text,outline=False):
    cls='button outline' if outline else 'button'
    return f'<a class="{cls}" href="{url}">{text}<span class="arrow" aria-hidden="true">↗</span></a>'
def text_link(url,text): return f'<a class="text-link" href="{url}">{text}<span aria-hidden="true">↗</span></a>'
def photo(name,alt,cls='',eager=False):
    loading='loading="eager" fetchpriority="high"' if eager else 'loading="lazy"'
    return f'<picture class="{cls}"><source type="image/webp" srcset="/assets/{name}-640.webp 640w, /assets/{name}-960.webp 960w, /assets/{name}-1672.webp 1672w" sizes="(max-width:680px) 100vw, (max-width:1400px) 90vw, 1280px"><img src="/assets/{name}-960.webp" alt="{esc(alt)}" width="1672" height="941" {loading} decoding="async"></picture>'
def nav_links(path):
    links=[]
    for url,label in NAV:
        current=' aria-current="page"' if path==url or (url=='/blog' and path.startswith('/blog/')) else ''
        links.append(f'<a href="{url}"{current}>{label}</a>')
    return ''.join(links)
def brand(): return '<a class="brand" href="/full1" aria-label="강남 퍼스트 홈"><span class="monogram" aria-hidden="true">GF</span><span class="brand-name">GANGNAM FIRST<small>PRIVATE LOUNGE · SEOUL</small></span></a>'
def header(path):
    return f'<a class="skip-link" href="#main">본문 바로가기</a><header class="site-header"><div class="header-inner container">{brand()}<nav class="desktop-nav" aria-label="주 메뉴">{nav_links(path)}</nav><a class="header-call" href="{TEL}">전화 문의 ↗</a><button class="menu-toggle" type="button" aria-expanded="false" aria-controls="mobile-menu">메뉴</button></div><nav class="mobile-nav" id="mobile-menu" aria-label="모바일 메뉴" hidden>{nav_links(path)}<a href="/location">방문 안내</a><a href="/faq">자주 묻는 질문</a></nav></header>'
def footer():
    return f'''<section class="contact-band" aria-label="전화 문의"><div class="container contact-inner"><div><span class="eyebrow">YOUR EVENING STARTS HERE</span><h2>오늘의 저녁을 함께 준비합니다.</h2><p>방문 시간과 인원, 출발 위치를 알려주세요.</p></div><a class="contact-phone" href="{TEL}">{PHONE} <span aria-hidden="true">↗</span></a></div></section><footer class="site-footer"><div class="container"><div class="footer-main"><div>{brand()}<p>음악과 대화, 그리고 여유로운 강남의 밤.<br>공간부터 이용과 이동까지, 강남 퍼스트.</p></div><nav class="footer-nav" aria-label="사이트 안내"><strong>EXPLORE</strong><a href="/about">퍼스트 소개</a><a href="/spaces">공간 소개</a><a href="/guide">이용 시간·요금</a><a href="/blog">퍼스트 저널</a></nav><nav class="footer-nav" aria-label="방문 도움말"><strong>PLAN YOUR VISIT</strong><a href="/pickup">강남권 픽업 서비스</a><a href="/location">지역별 방문 안내</a><a href="/faq">자주 묻는 질문</a><a href="{TEL}">{PHONE}</a></nav></div><div class="footer-bottom"><span>© 2026 GANGNAM FIRST. ALL RIGHTS RESERVED.</span><span>GANGNAM, SEOUL · 성인 대상 이용 안내</span></div></div></footer><div class="mobile-dock" aria-label="빠른 문의"><a href="/pickup">강남권 픽업 안내</a><a class="dock-call" href="{TEL}">전화 문의 <span aria-hidden="true">↗</span></a></div>'''
def breadcrumb(label,article=False):
    middle='<span aria-hidden="true">/</span><a href="/blog">블로그</a>' if article else ''
    return f'<nav class="breadcrumb" aria-label="현재 위치"><a href="/full1">HOME</a>{middle}<span aria-hidden="true">/</span><span aria-current="page">{esc(label)}</span></nav>'
def heading(label,title,intro,meta=''):
    return f'<div class="page-heading"><span class="eyebrow">{label}</span><h1>{title}</h1><p>{intro}</p>{meta}</div>'
def sidebar(items):
    return '<aside class="sidebar" aria-label="이 페이지의 내용"><span class="sidebar-label">ON THIS PAGE</span>'+''.join(f'<a href="#{anchor}">{label}</a>' for anchor,label in items)+'</aside>'
def cards(posts):
    return ''.join(f'''<a class="journal-card" href="/blog/{p['slug']}" data-category="{p['category']}"><span class="category">{p['label']}</span><span class="journal-no" aria-hidden="true">{POSTS.index(p)+1:02}</span><h3>{p['title']}</h3><p>{p['intro']}</p><span class="read-more">{p['category']} · {p['minutes']} MIN READ <span aria-hidden="true">↗</span></span></a>''' for p in posts)
def write_page(path,title,description,body,label,image=None,post=None,indexed=True):
    schema=[{'@context':'https://schema.org','@type':'WebSite','@id':ORIGIN+'/#website','name':'강남 퍼스트','url':ORIGIN+'/full1','inLanguage':'ko-KR'},{'@context':'https://schema.org','@type':'WebPage','name':title,'description':description,'url':ORIGIN+path,'inLanguage':'ko-KR','isPartOf':{'@id':ORIGIN+'/#website'}}]
    if path!='/full1':
        crumbs=[{'@type':'ListItem','position':1,'name':'홈','item':ORIGIN+'/full1'}]
        if post: crumbs.append({'@type':'ListItem','position':2,'name':'블로그','item':ORIGIN+'/blog'})
        crumbs.append({'@type':'ListItem','position':len(crumbs)+1,'name':label,'item':ORIGIN+path})
        schema.append({'@context':'https://schema.org','@type':'BreadcrumbList','itemListElement':crumbs})
    if post:
        article={'@context':'https://schema.org','@type':'BlogPosting','headline':post['title'],'description':description,'datePublished':DATE+'T00:00:00+09:00','dateModified':DATE+'T00:00:00+09:00','inLanguage':'ko-KR','mainEntityOfPage':ORIGIN+path,'author':{'@type':'Organization','name':'강남 퍼스트','url':ORIGIN+'/about'}}
        if image: article['image']=ORIGIN+f'/assets/{image}-1672.webp'
        schema.append(article)
    og_image=f'<meta property="og:image" content="{ORIGIN}/assets/{image}-1672.webp"><meta property="og:image:width" content="1672"><meta property="og:image:height" content="941">' if image else ''
    robots='<meta name="robots" content="noindex,follow">' if not indexed else '<meta name="robots" content="index,follow,max-image-preview:large">'
    schema_json=json.dumps(schema,ensure_ascii=False).replace('</','<\\/')
    kind='article' if post else 'website'
    page=f'''<!doctype html><html lang="ko"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1,viewport-fit=cover"><title>{esc(title)}</title><meta name="description" content="{esc(description)}"><link rel="canonical" href="{ORIGIN}{path}">{robots}<meta name="theme-color" content="#101311"><meta property="og:locale" content="ko_KR"><meta property="og:type" content="{kind}"><meta property="og:site_name" content="강남 퍼스트"><meta property="og:title" content="{esc(title)}"><meta property="og:description" content="{esc(description)}"><meta property="og:url" content="{ORIGIN}{path}">{og_image}<link rel="icon" href="/assets/favicon.svg" type="image/svg+xml"><link rel="stylesheet" href="/assets/site.css?v={CSS}"><script src="/assets/site.js?v={JS}" defer></script><script type="application/ld+json">{schema_json}</script></head><body>{header(path)}<main id="main">{body}</main>{footer()}</body></html>'''
    filename='index.html' if path=='/full1' else path.lstrip('/')+'/index.html'
    if not indexed: filename='404.html'
    output=PUBLIC/filename
    output.parent.mkdir(parents=True,exist_ok=True)
    output.write_text(page,encoding='utf-8')
    if indexed: ROUTES[path]=filename

