for post in POSTS:
    path='/blog/'+post['slug']
    photo_html=''
    if post.get('image'): photo_html=f'<figure class="wide-photo">{photo(post["image"],post["alt"],eager=True)}<figcaption class="photo-caption"><span>{post["caption"]}</span></figcaption></figure>'
    sections=''.join(f'<h2 id="section-{i}">{esc(title)}</h2>'+''.join(f'<p>{esc(p)}</p>' for p in paragraphs) for i,(title,paragraphs) in enumerate(post['sections']))
    link_html=''.join(button(url,label,True) for url,label in post['links'])
    related=[p for p in POSTS if p is not post][:3]
    article_meta=f'<div class="article-meta">{post["category"]} &nbsp; / &nbsp; 2026.11.18 &nbsp; / &nbsp; {post["minutes"]} MIN READ</div>'
    body=f'''<article class="container">{breadcrumb(post['title'],True)}{heading(post['label'],esc(post['title']),esc(post['intro']),article_meta)}{photo_html}<div class="article-layout">{sidebar([(f'section-{i}',title) for i,(title,_) in enumerate(post['sections'])])}<div class="prose">{sections}<div class="article-footer"><p>강남 퍼스트 · 방문을 준비하는 분들을 위한 안내</p><div class="button-row">{link_html}</div></div></div></article><section class="related"><div class="container"><span class="eyebrow">KEEP READING</span><h2>함께 읽으면 좋은 이야기</h2><div class="journal-grid">{cards(related)}</div></div></section>'''
    write_page(path,post['title']+' | 퍼스트 저널',post['description'],body,post['title'],post.get('image'),post)

